def narrow_quote(ci,evidence):
 full=original(ci,evidence)
 match=difflib.SequenceMatcher(None,full,evidence,autojunk=False).find_longest_match()
 if match.size>=6:
  start=match.a;end=start+match.size
  left=max(full.rfind('。',0,start),full.rfind('！',0,start),full.rfind('？',0,start))+1
  rights=[k for c in '。！？' if (k:=full.find(c,end))>=0]
  right=min(rights)+1 if rights else len(full)
  return full[left:right] or full
 return full

